#include "stdafx.h"#include "H_Class.h"static SBlockCreate WATCHDOG( "WATCHDOG", SH_WATCHDOG::Create );#include <HPARM_INIT.h> #include "ParmVarInfo.h"LIST_PARM(SH_WATCHDOG,W_WATCHDOG,5)void SH_WATCHDOG::InitParm(){#include "Blocks/WATCHDOG.h"   s_defFlag = SVarInfo::efParam;#include "Blocks/WATCHDOG_P.h"  qsort ( VarInfo, kVarInfo, sizeof ( SVarInfo ), CompVarInfo );}class WATCHDOG_IMPL : public W_WATCHDOG{public:  void StepT( SStepCalcParams &dt );};void SH_WATCHDOG::StepT( SStepCalcParams &dt ){  InputConnectionsTransfer();  WATCHDOG_IMPL *impl = reinterpret_cast<WATCHDOG_IMPL*>(W);  impl->StepT( dt );  OutputConnectionsTransfer();}//////////////////////////////////////////////////////////////////////////void WATCHDOG_IMPL::StepT( SStepCalcParams &dt ){  if( IN )  {    OUT = false;    waitIn = 0;    return;  }  waitIn += dt;  if( waitIn < DELAYTIME )    return;  waitIn = DELAYTIME + 1;  OUT = true;}